fn main() {
    let o = Some(concat("ab", "cd"));
    match o {
        Some(s) => print(str_len(s) * 5),
        None => print(0),
    }
    if let Some(s) = clone(o) {
        print(str_len(s) * 6);
    } else {
        print(0);
    }
}

fn main() {
    let s = "ab";
    print(str_len(s) * 10);
    let i = 0;
    let total = 0;
    while i < 3 {
        let t = s.clone(); // Clone the string before using it in the loop
        total = total + str_len(t) * 5;
        i = i + 1;
    }
    print(total);
}

fn total(v: Vec<Int>, flag: Bool) -> Int {
    let w = v.clone(); // Clone the vector to avoid double move error
    if flag {
        return len(w) * 10;
    }
    let u = push(v, 3);
    len(u) * 20
}

fn main() {
    print(total(push(push(vec(), 1), 2), true));
    print(total(push(push(vec(), 1), 2), false));
}

fn f(o: Option<Vec<Int>>) -> Option<Int> {
    let v = o?;
    let w = o?; // Fix by cloning at the earlier site or reordering
    Some(len(v) * 10 + len(w))
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

